  30: $approvedProviderOriginDeclarations = @(
  31:     (Join-Path $sourceRoot `
  32:         'java\com\bettingproject\sofascorelocal\domain\provider\ScheduledEventsProviderPageRequest.java'),
  33:     (Join-Path $sourceRoot `
  34:         'java\com\bettingproject\sofascorelocal\domain\provider\EventDetailsProviderRequest.java'),
  35:     (Join-Path $sourceRoot `
  36:         'java\com\bettingproject\sofascorelocal\domain\provider\TournamentScheduledEventsProviderRequest.java')
  37: )
  38: $approvedProviderOriginLine =
  39:     'public static final String EXPECTED_ORIGIN = "https://www.sofascore.com";'
  40: 
  41: $violations = @()
  42: foreach ($pattern in $forbiddenPatterns) {
  43:     $matches = $sourceFiles |
  44:         Select-String -Pattern $pattern -CaseSensitive:$false
  45:     if ($pattern -eq $forbiddenPatterns[0]) {
  46:         $matches = $matches | Where-Object {
  47:             -not ($_.Path -in $approvedProviderOriginDeclarations -and
  48:                 $_.Line.Trim() -ceq $approvedProviderOriginLine)
  49:         }
  50:     }
  51:     if ($matches) {
  52:         $violations += $matches
  53:     }
  54: }
