300:     private void finishStandalone(Standalone access) {
301:         try {access.release();ownedStandaloneId=null;return;}
302:         catch(RuntimeException failure) {pendingCleanup=access;runtimeReason="PROVIDER_CLEANUP_REQUIRED";}
303:         // Only this original owner can release its lease, after explicit local cleanup.
304:         while(!stopping) {
305:             synchronized(cleanupMonitor) {
306:                 while(!cleanupRequested && !stopping) {
307:                     try {cleanupMonitor.wait();}
308:                     catch(InterruptedException interrupted) {Thread.currentThread().interrupt();return;}
309:                 }
310:                 cleanupRequested=false;
311:             }
312:             if(stopping) return;
313:             try {access.release();pendingCleanup=null;ownedStandaloneId=null;runtimeReason=null;return;}
314:             catch(RuntimeException failure) {runtimeReason="PROVIDER_CLEANUP_REQUIRED";}
315:         }
316:     }
