  60:             if (sourceSnapshotIds.isEmpty() || sourceSnapshotIds.stream().anyMatch(id -> id == null || id < 1)
  61:                     || sourceSnapshotIds.stream().distinct().count() != sourceSnapshotIds.size())
  62:                 throw new IllegalArgumentException("Invalid tournament sources");
  63:             if (exclusionReason != null && !exclusionReason.matches("[A-Z0-9_]{1,96}"))
  64:                 throw new IllegalArgumentException("Invalid exclusion reason");
  65:         }
  66:         public boolean eligible() { return exclusionReason == null; }
  67:         public J3TournamentCatalogOption option() {
  68:             if (!eligible()) throw new IllegalStateException("Tournament is not eligible");
  69:             return new J3TournamentCatalogOption(tournamentId, name, category, uniqueTournamentId,
  70:                     uniqueTournamentName, timezoneEventCount, sourceSnapshotIds);
