  48:             if(file==null || file.isEmpty() || file.getOriginalFilename()==null
  49:                     || !file.getOriginalFilename().matches("page-([1-9]|[12][0-9]|3[0-5])\\.json"))
  50:                 throw new IllegalArgumentException("J3_IMPORT_NAMES_INVALID");
  51:             if(file.getSize()>RawPayloadEvidence.MAXIMUM_BYTES || (total+=file.getSize())>25L*1024*1024)
  52:                 throw new IllegalArgumentException("J3_IMPORT_SIZE_LIMIT");
  53:             int page=Integer.parseInt(file.getOriginalFilename().substring(5,file.getOriginalFilename().length()-5));
  54:             try {
  55:                 if(ordered.putIfAbsent(page,RawPayloadEvidence.capture(file.getBytes()))!=null)
  56:                     throw new IllegalArgumentException("J3_IMPORT_DUPLICATE_PAGE");
  57:             } catch(IOException unreadable) {throw new IllegalArgumentException("J3_IMPORT_READ_FAILED");}
  58:         }
  59:         if(ordered.firstKey()!=1 || ordered.lastKey()!=ordered.size()) throw new IllegalArgumentException("J3_IMPORT_PAGE_GAP");
