 832:     private boolean cleanup(Session s, LiveProviderSession transport,
 833:                             ManualProviderRequestCoordinator.CampaignLease lease) {
 834:         boolean absent = false, cleaned = false, exclusionRequested = false;
 835:         LiveCampaignDiagnostic.Phase phase = CLEANUP_TRANSPORT_CLOSE;
 836:         try {
 837:             if (!s.transportClosed && transport != null) transport.close();
 838:             phase = CLEANUP_TRANSPORT_ABSENCE;
 839:             absent = supervisor.activeCampaignId().filter(s.manifest.campaignId()::equals).isEmpty();
 840:             if (!absent) throw new IllegalStateException("LIVE_PROVIDER_CLEANUP_UNVERIFIED");
 841:             s.transportClosed = true;
 842:             phase = CLEANUP_DIAGNOSTIC_PUBLICATION;
 843:             persistDiagnostics(s);
 844:             if (s.ownership != null && !s.executionReconciled) {
 845:                 // This transaction locks the same guard row as launch. Its successful return
 846:                 // settles any earlier commit whose response was lost before PREPARED can be
 847:                 // used as evidence, and closes further dispatch admission for this owner.
 848:                 exclusionRequested = true;
 849:                 phase = CLEANUP_EXCLUSION;
 850:                 guard.requireCleanup(s.ownership, clock.instant());
 851:                 phase = CLEANUP_STATE_READ;
 852:                 CampaignView current = state(s.manifest.campaignId());
 853:                 if (!unlaunchedPreparation(s, current)) {
 854:                     phase = CLEANUP_OWNERSHIP_CHECK;
 855:                     if (!s.ownership.equals(current.ownership()))
 856:                         throw new IllegalStateException("LIVE_CLEANUP_OWNERSHIP_CHANGED");
 857:                     String terminal = s.stopReason != null ? s.stopReason
 858:                             : s.schedule != null && s.schedule.globalStop() != null ? s.schedule.globalStop() : "COMPLETED";
 859:                     phase = CLEANUP_SCHEDULE_PUBLICATION;
 860:                     if (s.schedule != null) publishStates(s);
 861:                     else {
 862:                         // The launch may have committed before its response was lost. Its durable
 863:                         // owner and events are authoritative even though no schedule was created.
 864:                         for (EventView event : current.events()) {
 865:                             publishState(s, new LiveSchedule.EventState(event.target().canonicalEventId(), terminal,
 866:                                     null, null, event.missedCycles(), event.finalComplete()));
 867:                         }
 868:                     }
 869:                     phase = CLEANUP_ATTEMPT_RECONCILIATION;
 870:                     resolveUnpublishedAttempts(s, current);
 871:                     phase = CLEANUP_TERMINAL_PUBLICATION;
 872:                     store.transition(s.ownership, null, terminal, terminal, clock.instant(), null);
 873:                 }
 874:                 // A preparation that never launched (including a concurrent cancellation) has
 875:                 // no execution ledger to close. Preserve it and release only the acquired lease.
 876:                 s.executionReconciled = true;
 877:             }
 878:             if (lease != null) {
 879:                 phase = CLEANUP_LEASE_RELEASE;
 880:                 if (s.leaseCloseAttempted) lease.retryCloseAfterVerifiedCleanup();
 881:                 else { s.leaseCloseAttempted = true; lease.close(); }
 882:             }
 883:             cleaned = true;
 884:             active.compareAndSet(s, null);
 885:             return true;
 886:         } catch (RuntimeException failure) {
 887:             s.cleanupFailure = LiveCampaignDiagnostic.from(phase, failure, clock.instant());
 888:             logFailure(s, "CLEANUP_FAILURE", s.cleanupFailure);
 889:             if(diagnostics!=null) {
 890:                 try { diagnostics.recordFailure(s.manifest.campaignId(),LiveDiagnosticStore.Kind.CLEANUP_FAILURE,s.cleanupFailure); }
 891:                 catch(RuntimeException unavailable) { /* Keep evidence in the owning session until explicit local cleanup. */ }
 892:             }
 893:             if (!absent) {
 894:                 try { supervisor.stopCampaign(s.manifest.campaignId(), LiveProviderSession.ENDPOINTS); }
 895:                 catch (RuntimeException ignored) { /* unverifiable transport remains excluded */ }
 896:             }
 897:             if (s.ownership != null && !exclusionRequested) {
 898:                 try { guard.requireCleanup(s.ownership, clock.instant()); }
 899:                 catch (RuntimeException ignored) { /* SQL failure must never release durable exclusion */ }
 900:             }
 901:             if (lease == null) active.compareAndSet(s, null);
 902:             return false;
 903:         } finally {
 904:             s.completeCleanup(cleaned);
 905:         }
 906:     }
