1274:     @EventListener(ApplicationReadyEvent.class)
1275:     public void markProvenOrphanWithoutRestart() {
1276:         Guard g = guard.snapshot();
1277:         if (g.owner() == null || "FREE".equals(g.state())) return;
1278:         Optional<ProcessHandle> process = ProcessHandle.of(g.owner().processId());
1279:         if (process.isPresent() && process.orElseThrow().isAlive()) {
1280:             Optional<Instant> observedStart = process.orElseThrow().info().startInstant();
1281:             if (observedStart.isEmpty()) return; // An inaccessible identity is not proof of death.
1282:             if (observedStart.orElseThrow().truncatedTo(java.time.temporal.ChronoUnit.MICROS)
1283:                     .equals(g.owner().processStartedAt().truncatedTo(java.time.temporal.ChronoUnit.MICROS))) return;
1284:         }
1285:         // No automatic release: an orphan worker may still exist even when its parent died.
1286:         // A guard may also have been acquired in the small window before store.launch. That
1287:         // PREPARED row has no execution owner, so it must remain a preparation and is made
1288:         // available only to the explicit, process-verified pre-launch recovery path.
1289:         CampaignView campaign = store.find(g.campaignId()).orElse(null);
1290:         if (!unlaunchedPreparation(campaign) && campaign != null)
1291:             store.interruptOrphan(g.ownership(), clock.instant(), "OWNER_PROCESS_ABSENT");
1292:         guard.requireCleanup(g.ownership(), clock.instant());
1293:     }
