284:     public static GetCommand readGetCommand(DataInputStream input) throws IOException {
285:         Objects.requireNonNull(input, "input");
286:         Endpoint endpoint = readEndpoint(input.readUTF());
287:         try {
288:             return switch (endpoint) {
289:                 case SCHEDULED_EVENTS -> new GetCommand(
290:                         endpoint, readDate(input.readUTF()), input.readInt(), 0, 0,
291:                         input.readInt());
292:                 case TOURNAMENT_SCHEDULED_EVENTS -> new GetCommand(
293:                         endpoint, readDate(input.readUTF()), 0, input.readLong(), 0,
294:                         input.readInt());
295:             case EVENT_DETAILS, EVENT_STATISTICS, EVENT_INCIDENTS, EVENT_LINEUPS -> new GetCommand(
296:                     endpoint, null, 0, 0, input.readLong(), input.readInt());
297:             };
298:         }
299:         catch (IllegalArgumentException exception) {
300:             throw new ProtocolValidationException(readFailureCode(exception), exception);
