340:     public static boolean requireStart(DataInputStream input)
341:             throws IOException, ProtocolValidationException {
342:         Objects.requireNonNull(input, "input");
343:         int command=input.readUnsignedByte();
344:         if (command != START && command != START_WITH_J3_PAUSE) {
345:             throw new ProtocolValidationException(FailureCode.PROTOCOL_ERROR);
346:         }
