352:     public static J3Scope readJ3Scope(DataInputStream input,java.time.Instant now) throws IOException,ProtocolValidationException {
353:         try {
354:             java.util.UUID id=readScopeId(input);
355:             String text=input.readUTF();LocalDate date=LocalDate.parse(text);
356:             if(text.length()!=10 || !date.toString().equals(text))throw new IllegalArgumentException();
357:             java.time.Instant deadline=java.time.Instant.ofEpochMilli(input.readLong());
358:             if(!deadline.isAfter(now) || deadline.isAfter(now.plusSeconds(1200)))throw new IllegalArgumentException();
359:             return new J3Scope(id,date,deadline);
360:         } catch(IllegalArgumentException | java.time.DateTimeException invalid) {
361:             throw new ProtocolValidationException(FailureCode.PROTOCOL_ERROR);
362:         }
363:     }
364:     public static java.util.UUID readScopeId(DataInputStream input) throws IOException,ProtocolValidationException {
365:         try {
366:             String value=input.readUTF();java.util.UUID id=java.util.UUID.fromString(value);
367:             if(!id.toString().equals(value))throw new IllegalArgumentException();return id;
368:         } catch(IllegalArgumentException invalid) {throw new ProtocolValidationException(FailureCode.PROTOCOL_ERROR);}
369:     }
370:     public static void writeScopeAcknowledgement(DataOutputStream output,byte frame,java.util.UUID id) throws IOException {
371:         if(frame!=J3_READY && frame!=J3_CLOSED)throw new IllegalArgumentException("Invalid scope acknowledgement");
372:         output.writeByte(frame);output.writeUTF(id.toString());output.flush();
373:     }
