493:     private static LocalDate readDate(String value) throws ProtocolValidationException {
494:         if (value == null || !value.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}")) {
495:             throw new ProtocolValidationException(FailureCode.INVALID_DATE);
496:         }
497:         try {
498:             LocalDate parsed = LocalDate.parse(value);
499:             if (!parsed.toString().equals(value)) {
500:                 throw new ProtocolValidationException(FailureCode.INVALID_DATE);
501:             }
502:             return parsed;
503:         }
504:         catch (DateTimeParseException exception) {
505:             throw new ProtocolValidationException(FailureCode.INVALID_DATE, exception);
506:         }
507:     }
