509:     private static FailureCode readFailureCode(IllegalArgumentException exception) {
510:         try {
511:             return FailureCode.valueOf(exception.getMessage());
512:         }
513:         catch (RuntimeException ignored) {
514:             return FailureCode.PROTOCOL_ERROR;
515:         }
516:     }
