 496:     private PlaywrightProviderResponse execute(CampaignState state,PlaywrightProviderRequest request,
 497:             PlaywrightDispatchAdmission admission,LiveProviderDispatchGroup group,J3ProviderSubOperation j3Scope) {
 498:         Objects.requireNonNull(request, "request");
 499:         requireActive(state);
 500:         requireDispatchScope(state,request,j3Scope);
 501:         LiveProviderGroupTracker groups=j3Scope==null?state.liveGroups:null;
 502:         if (j3Scope==null && !state.allowedEndpoints.contains(request.endpoint())) {
 503:             throw new PlaywrightProviderException(PlaywrightProviderFailure.INVALID_ENDPOINT);
 504:         }
 505:         if (request.ifNoneMatch().isPresent()
 506:                 && (groups == null || !groups.usesConditionalRevalidation())) {
 507:             throw new PlaywrightProviderException(PlaywrightProviderFailure.INVALID_REQUEST);
 508:         }
 509:         if (group != null && groups == null)
 510:             throw new PlaywrightProviderException(PlaywrightProviderFailure.INVALID_REQUEST);
 511:         state.ioLock.lock();
 512:         boolean dispatchStarted = false;
 513:         boolean usableResponseEvidence = false;
 514:         boolean recoverableTimeoutEvidence = false;
 515:         PlaywrightTransportDiagnostic diagnostic = null;
 516:         try {
 517:             requireActive(state);
 518:             try {
 519:                 DataOutputStream output = Objects.requireNonNull(state.output, "output");
 520:                 DataInputStream sourceInput = Objects.requireNonNull(state.input, "input");
 521:                 int timeoutMillis = toMillis(properties.getRequestTimeout());
 522:                 long responseDeadline;
 523:                 long requestDeadline;
 524:                 boolean conditionalWire = groups != null && groups.usesConditionalRevalidation();
 525:                 boolean continuation = groups != null && groups.isContinuation(request, group);
 526:                 Runnable continuationGuard = () -> { requireActive(state); requireDispatchScope(state,request,j3Scope); admission.check(); };
 527:                 // Historical grouped continuations retain their no-pause protocol. V8, V9 and V10
 528:                 // deliberately share the qualified 500 ms local-pressure fence after every
 529:                 // family exchange, including J5 continuations.
 530:                 if (continuation && !groups.requiresPostExchangeFenceForContinuation())
 531:                     providerNetworkStartDelayGate.admitGroupContinuation(continuationGuard);
 532:                 else providerNetworkStartDelayGate.awaitNextGroupDispatch(
 533:                         group == null ? null : groups, continuationGuard);
 534:                 try (PlaywrightDispatchAdmission.Permit permit = admission.acquireDispatchPermit()) {
 535:                     // Admission may perform durable checks. Never hold the supervisor stop lock during SQL.
 536:                     state.dispatchLock.lock();
 537:                     try {
 538:                     requireActive(state);
 539:                     requireDispatchScope(state,request,j3Scope);
 540:                     if(j3Scope!=null)state.lastJ3Page=request.page();
 541:                     if (groups != null) groups.dispatched(request, group);
 542:                     state.providerDispatchStarted.set(true);
 543:                     dispatchStarted = true;
 544:                     boolean supportsProvenTimeoutRecovery = groups != null
 545:                             && groups.supportsProvenTimeoutRecovery();
 546:                     requestDeadline = System.nanoTime() + properties.getRequestTimeout().toNanos();
 547:                     responseDeadline = requestDeadline + Duration.ofSeconds(
 548:                             supportsProvenTimeoutRecovery ? 3 : 1).toNanos();
 549:                     output.writeByte(j3Scope!=null ? GET_J3 : conditionalWire ? GET_LIVE_V9
 550:                             : supportsProvenTimeoutRecovery ? GET_LIVE_V6 : GET);
 551:                     if(j3Scope!=null)output.writeUTF(j3Scope.runId().toString());
 552:                     output.writeUTF(request.endpoint().name());
 553:                     switch (request.endpoint()) {
 554:                         case SCHEDULED_EVENTS -> {
 555:                             output.writeUTF(request.date().toString());
 556:                             output.writeInt(request.page());
 557:                         }
 558:                         case TOURNAMENT_SCHEDULED_EVENTS -> {
 559:                             output.writeUTF(request.date().toString());
 560:                             output.writeLong(request.uniqueTournamentId());
 561:                         }
 562:                         case EVENT_DETAILS, EVENT_STATISTICS, EVENT_INCIDENTS, EVENT_LINEUPS ->
 563:                                 output.writeLong(request.eventId());
 564:                         default -> throw new PlaywrightProviderException(
 565:                                 PlaywrightProviderFailure.INVALID_ENDPOINT);
 768:     private void requireDispatchScope(CampaignState state,PlaywrightProviderRequest request,J3ProviderSubOperation scope) {
 769:         if(scope==null) {
 770:             if(state.j3Scope!=null)throw new PlaywrightProviderException(PlaywrightProviderFailure.INVALID_REQUEST);
 771:             return;
 772:         }
 773:         if(!scope.equals(state.j3Scope) || Thread.currentThread()!=state.controlOwner
 774:                 || request.endpoint()!=SofascoreEndpointType.SCHEDULED_EVENTS || !scope.date().equals(request.date())
 775:                 || request.page()<=state.lastJ3Page || request.page()>35 || request.ifNoneMatch().isPresent()
 776:                 || !clock.instant().plus(properties.getRequestTimeout()).plusSeconds(5).isBefore(scope.deadline()))
 777:             throw new PlaywrightProviderException(PlaywrightProviderFailure.INVALID_REQUEST);
 778:     }
